let lang = document.documentElement.lang || "mk";
let products = [];
const $ = id => document.getElementById(id);
const t = k => (translations[lang] && translations[lang][k]) || translations.mk[k] || k;

function applyLang() {
  document.documentElement.lang = lang;
  document.querySelectorAll("[data-i18n]").forEach(el => { 
    let k = el.dataset.i18n; 
    if (translations[lang] && translations[lang][k]) el.textContent = translations[lang][k]; 
  });
  document.querySelectorAll("[data-i18n-placeholder]").forEach(el => { 
    let k = el.dataset.i18nPlaceholder; 
    if (translations[lang] && translations[lang][k]) el.placeholder = translations[lang][k]; 
  });
  if ($("langToggle")) $("langToggle").textContent = lang === "mk" ? "EN / МК" : "МК / EN";
  if ($("year")) $("year").textContent = new Date().getFullYear();
  renderProducts();
}

if ($("langToggle")) {
  $("langToggle").addEventListener("click", () => { 
    lang = lang === "mk" ? "en" : "mk"; 
    try { localStorage.setItem("vc-lang", lang); } catch (e) { } 
    applyLang(); 
  });
}

function readProducts() { 
  try { products = JSON.parse(localStorage.getItem("vc-products") || "[]"); } catch (e) { products = []; } 
}

function saveProducts() { 
  try { 
    localStorage.setItem("vc-products", JSON.stringify(products)); 
    return true; 
  } catch (e) { 
    showToast(lang === "mk" ? "Прелистувачот нема доволно простор. Обиди се со помала фотографија." : "Browser storage is full. Try a smaller photo."); 
    return false; 
  } 
}

function renderProducts() {
  const grid = $("productGrid");
  if (!grid) return;
  const q = $("searchProducts") ? $("searchProducts").value.toLowerCase() : "";
  const cat = $("filterCategory") ? $("filterCategory").value : "all";
  const filtered = products.filter(p => (p.name + " " + (p.note || "")).toLowerCase().includes(q) && (cat === "all" || p.category === cat));
  grid.innerHTML = "";
  if (!filtered.length) { 
    const d = document.createElement("div"); 
    d.className = "empty"; 
    d.textContent = products.length ? t("noMatches") : t("emptyProducts"); 
    grid.appendChild(d); 
    return; 
  }
  filtered.forEach(p => {
    const card = document.createElement("article"); card.className = "product";
    const img = document.createElement("img"); img.src = p.photo; img.alt = p.name; img.loading = "lazy"; card.appendChild(img);
    const info = document.createElement("div"); info.className = "product-info";
    const h = document.createElement("h3"); h.textContent = p.name; info.appendChild(h);
    const price = document.createElement("p"); price.className = "product-price"; price.textContent = p.price + " " + t("priceUnit"); info.appendChild(price);
    const detail = document.createElement("p"); detail.textContent = (p.note || "") + (p.note ? " · " : "") + t("category") + ": " + categoryLabel(p.category); info.appendChild(detail);
    const actions = document.createElement("div"); actions.className = "product-actions"; 
    const del = document.createElement("button"); del.type = "button"; del.className = "mini-btn"; del.textContent = t("delete"); 
    del.addEventListener("click", () => { 
      products = products.filter(x => x.id !== p.id); 
      saveProducts(); 
      renderProducts(); 
      showToast(t("deleted")); 
    }); 
    actions.appendChild(del); info.appendChild(actions); card.appendChild(info); grid.appendChild(card);
  });
}

function categoryLabel(c) { 
  const map = { "Облека": "catClothes", "Обувки": "catShoes", "Аксесоари": "catAccessories" }; 
  return t(map[c] || c); 
}

if ($("searchProducts")) $("searchProducts").addEventListener("input", renderProducts);
if ($("filterCategory")) $("filterCategory").addEventListener("change", renderProducts);

if ($("productForm")) {
  $("productForm").addEventListener("submit", e => {
    e.preventDefault(); 
    const file = $("productPhoto").files[0]; 
    if (!file) { showToast(t("needPhoto")); return; }
    if (!file.type.startsWith("image/")) { showToast(t("needPhoto")); return; }
    const reader = new FileReader(); 
    reader.onload = () => {
      const item = { 
        id: Date.now().toString(36) + Math.random().toString(36).slice(2, 7), 
        name: $("productName").value.trim(), 
        price: $("productPrice").value, 
        category: $("productCategory").value, 
        note: $("productNote").value.trim(), 
        photo: reader.result 
      };
      products.unshift(item); 
      if (saveProducts()) { 
        renderProducts(); 
        $("productForm").reset(); 
        showToast(t("added")); 
      }
    }; 
    reader.readAsDataURL(file);
  });
}

function showToast(msg) { 
  const el = $("toast"); 
  if (!el) return;
  el.textContent = msg; 
  el.classList.add("show"); 
  clearTimeout(window.vcToast); 
  window.vcToast = setTimeout(() => el.classList.remove("show"), 2600); 
}

// Cookie banner logic
const cookieBanner = $("cookieBanner"), cookieSettings = $("cookieSettings");
function cookieChoice() { try { return localStorage.getItem("vc-cookie-choice"); } catch (e) { return null; } }
function showCookie() { if (cookieBanner && !cookieChoice()) cookieBanner.classList.add("show"); }
function saveCookieChoice(choice) { 
  try { 
    localStorage.setItem("vc-cookie-choice", choice); 
    if (choice === "accepted" && $("preferenceCookies") && $("preferenceCookies").checked) 
      localStorage.setItem("vc-cookie-preferences", "yes"); 
    else 
      localStorage.removeItem("vc-cookie-preferences"); 
  } catch (e) { } 
  if (cookieBanner) cookieBanner.classList.remove("show"); 
  if (cookieSettings) cookieSettings.classList.remove("show"); 
  showToast(t("cookieSaved")); 
}

if ($("cookieAccept")) $("cookieAccept").addEventListener("click", () => { if ($("preferenceCookies")) $("preferenceCookies").checked = true; saveCookieChoice("accepted"); });
if ($("cookieReject")) $("cookieReject").addEventListener("click", () => { if ($("preferenceCookies")) $("preferenceCookies").checked = false; saveCookieChoice("rejected"); });
if ($("cookieOptions")) {
  $("cookieOptions").addEventListener("click", () => { 
    if (cookieSettings) {
      cookieSettings.classList.toggle("show"); 
      $("cookieOptions").textContent = cookieSettings.classList.contains("show") ? (lang === "mk" ? "Сокриј поставки" : "Hide settings") : t("cookieOptions"); 
    }
  });
}
if ($("cookieSettingsLink")) {
  $("cookieSettingsLink").addEventListener("click", e => { 
    e.preventDefault(); 
    if (cookieBanner) cookieBanner.classList.add("show"); 
    if (cookieSettings) cookieSettings.classList.add("show"); 
  });
}

document.addEventListener("DOMContentLoaded", () => {
  readProducts(); 
  applyLang(); 
  showCookie();
});
